// The entity catalog: every entity type, its props (types, ranges, defaults), the art style
// presets and the engine kits.
//
// The source of truth is the TypeScript format package. format/catalog.json (generated by
// `pnpm -C format catalog`) and kits/*/kit.json are embedded into the engine at
// build time, so the C++ loader and the TS validator always agree on what a package may contain.
#pragma once

#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace dreamsy::pkg {

enum class Dimension { Any, D2, D3 };
enum class AssetKind { Image, Mesh, Audio, Font };
enum class PropKind { Number, Int, Bool, String, Vec2, Vec3, Color, Enum, Asset, Entity };

const char* dimension_name(Dimension d);  // "any" | "2d" | "3d"
const char* asset_kind_name(AssetKind k);  // "image" | ...
std::optional<AssetKind> asset_kind_from(std::string_view name);

// A typed prop value. Which field is used depends on `kind`:
//   Number, Int        -> num[0]
//   Vec2, Vec3         -> num[0..1] / num[0..2]
//   Bool               -> flag
//   String, Color, Enum, Asset ("asset:<id>"), Entity (an entity id) -> text
struct PropValue {
  PropKind kind = PropKind::Number;
  double num[3] = {0, 0, 0};
  bool flag = false;
  std::string text;
};

struct PropDef {
  std::string name;
  PropKind kind = PropKind::Number;
  std::optional<double> min, max;      // Number, Int
  std::optional<size_t> max_length;    // String
  std::vector<std::string> values;     // Enum
  AssetKind asset_kind = AssetKind::Image;  // Asset
  std::optional<PropValue> default_value;   // absent = unset (e.g. no texture)
};

struct EntityType {
  std::string name;
  Dimension dimension = Dimension::Any;
  bool container = false;
  std::vector<PropDef> props;  // catalog order

  const PropDef* prop(std::string_view key) const;
};

struct StyleDef {
  std::string name;
  std::vector<std::string> dimensions;  // "2d", "3d"
};

struct KitDef {
  std::string name;
  std::vector<std::string> requires_kits;  // kit.json "requires"
};

class Catalog {
 public:
  // The embedded catalog, parsed on first use. Aborts if the embedded data is corrupt (a
  // build problem, never a package problem).
  static const Catalog& get();

  const EntityType* type(std::string_view name) const;
  const StyleDef* style(std::string_view name) const;
  const KitDef* kit(std::string_view name) const;

  const std::vector<EntityType>& types() const { return types_; }
  const std::vector<KitDef>& kits() const { return kits_; }
  std::string kit_names() const;  // "ai, combat, core, ..." (alphabetical)

  // Listed kits plus their dependencies, transitively, in discovery order (format/src/kits.ts expandKits).
  std::vector<std::string> expand_kits(const std::vector<std::string>& listed) const;

 private:
  Catalog() = default;
  std::vector<EntityType> types_;
  std::vector<StyleDef> styles_;
  std::vector<KitDef> kits_;
};

}  // namespace dreamsy::pkg
